struct po
{
    float m[4][4];
};

struct entity;

struct link_interface
{
    char padding[8];
    entity *parent;
};

struct entity_vtable
{
    char padding[64];
    short adjustment;
    short reserved;
    void (*po_changed)(void *);
};

struct entity
{
    char padding0[8];
    entity_vtable *vtable;
    po my_po;
    link_interface *link;

    void set_rel_po(const po &the_po);
};

extern void update_abs_po_family(link_interface *);

asm(".equ update_abs_po_family__14link_interface, 0x00122198");

void entity::set_rel_po(const po &the_po)
{
    my_po = the_po;
    update_abs_po_family(link);
    entity_vtable *table = vtable;
    table->po_changed((char *)this + table->adjustment);
}

class FEEntityManager
{
    char padding[0x2a0];
    po surfer_select_po;

public:
    void SetSurferPo(entity *s, int s_num);
};

void FEEntityManager::SetSurferPo(entity* s, int s_num)
{
	s->set_rel_po(surfer_select_po);
}
